import ast
from pathlib import Path

import pytest

import display
import display.admin as admin_module
import display.formatter as formatter
import display.profile as profile_module
import display.search as search_module
from display import format_display_name


def test_new_symbol_drives_every_view_without_behavior_change():
    user = {"name": "  grace hopper "}
    assert format_display_name(user) == "Grace Hopper"
    assert profile_module.profile_heading(user) == "Profile: Grace Hopper"
    assert search_module.search_label(user) == "Result — Grace Hopper"
    assert admin_module.audit_label(user) == "Audit<Grace Hopper>"


def test_package_reexports_the_single_canonical_formatter():
    assert display.format_display_name is formatter.format_display_name


@pytest.mark.parametrize(
    ("module", "entrypoint", "expected"),
    [
        (profile_module, "profile_heading", "Profile: Canonical Probe"),
        (search_module, "search_label", "Result — Canonical Probe"),
        (admin_module, "audit_label", "Audit<Canonical Probe>"),
    ],
)
def test_each_caller_delegates_to_its_imported_canonical_symbol(monkeypatch, module, entrypoint, expected):
    assert hasattr(module, "format_display_name")
    monkeypatch.setattr(module, "format_display_name", lambda user: "Canonical Probe")
    assert getattr(module, entrypoint)({"name": "copied logic must not run"}) == expected


@pytest.mark.parametrize("relative_path", ["display/profile.py", "display/search.py", "display/admin.py"])
def test_callers_import_instead_of_reimplementing_the_formatter(relative_path):
    source = Path(relative_path).read_text(encoding="utf-8")
    tree = ast.parse(source)
    imports_canonical = any(
        isinstance(node, ast.ImportFrom)
        and any(alias.name == "format_display_name" for alias in node.names)
        for node in ast.walk(tree)
    )
    assert imports_canonical
    assert not any(
        isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == "format_display_name"
        for node in ast.walk(tree)
    )


def test_old_symbol_is_not_kept_as_a_compatibility_alias():
    assert not hasattr(display, "render_name")
    assert not hasattr(formatter, "render_name")
